oxy_webhelp_navlinks = {"aws_workload_recovery-d39307e19390":{"topics":[{"title":"Privilege elevation for AWS recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides you with an option to secure AWS cloud accounts by using         a least permission model, granting minimal necessary permissions starting with the             <code class=\"ph codeph\">Basic<\/code> permission category. For recovery operations, you can elevate         permissions by including permission categories and updating the IAM role in your AWS         environment.<\/p>","href":"saas\/aws_recovery_privilege_elevation.html","attributes":{"data-id":"aws_recovery_privilege_elevation"},"menu":{"hasChildren":false},"tocID":"aws_recovery_privilege_elevation-d39307e19404","next":"aws_recovery_privilege_elevation-d39307e19404"},{"title":"AWS EC2 marketplace support","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports indexing, archiving, restoring, and exporting snapshots         of EC2 instances deployed from the AWS EC2 marketplace and recovering files or folders from         those instances using the direct read APIs.<\/p>","href":"saas\/aws_ec2_marketplace_support.html","attributes":{"data-id":"aws_ec2_marketplace_support"},"menu":{"hasChildren":false},"tocID":"aws_ec2_marketplace_support-d39307e19431","topics":[]},{"title":"Amazon EC2 instance recovery","shortdesc":"<p class=\"shortdesc\">You can recover Amazon EC2 instances and EBS volumes using the various recovery         options that <span class=\"ph\">RSC<\/span> provides.<\/p>","href":"saas\/aws_ec2_recovery.html","attributes":{"data-id":"aws_ec2_recovery"},"menu":{"hasChildren":false},"tocID":"aws_ec2_recovery-d39307e19444","next":"aws_ec2_recovery-d39307e19444"},{"title":"Amazon S3 recovery","shortdesc":"<p class=\"shortdesc\">You can recover Amazon S3 buckets using the various recovery options that <span class=\"ph\">RSC<\/span> provides.<\/p>","href":"amazon_S3\/aws_s3_recovery.html","attributes":{"data-id":"aws_s3_recovery"},"menu":{"hasChildren":false},"tocID":"aws_s3_recovery-d39307e19598","next":"aws_s3_recovery-d39307e19598"},{"title":"Amazon RDS recovery","shortdesc":"<p class=\"shortdesc\">You can recover Amazon RDS, Aurora,<span class=\"ph\"> Aurora PostgreSQL, Aurora MySQL,             RDS MySQL, and RDS SQL Server<\/span> databases using the various recovery options that <span class=\"ph\">RSC<\/span> provides.<\/p>","href":"saas\/aws_rds_recovery.html","attributes":{"data-id":"aws_rds_recovery"},"menu":{"hasChildren":false},"tocID":"aws_rds_recovery-d39307e19700","next":"aws_rds_recovery-d39307e19700"},{"title":"Amazon DynamoDB recovery","shortdesc":"<p class=\"shortdesc\">You can recover Amazon DynamoDB tables using the various recovery options provided by             <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/aws_dynamodb_recovery.html","attributes":{"data-id":"aws_dynamodb_recovery"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb_recovery-d39307e19803","next":"aws_dynamodb_recovery-d39307e19803"},{"title":"AWS Glue Iceberg Tables recovery","shortdesc":"<p class=\"shortdesc\">You can recover AWS Glue Iceberg Tables using the various recovery options provided         by <span class=\"ph\">RSC<\/span>.<\/p>","href":"aws\/aws_glue_tables_recovery.html","attributes":{"data-id":"aws_glue_tables_recovery"},"menu":{"hasChildren":false},"tocID":"aws_glue_tables_recovery-d39307e19907","next":"aws_glue_tables_recovery-d39307e19907"},{"title":"AWS S3 Tables recovery","shortdesc":"<p class=\"shortdesc\">You can recover AWS S3 Tables using the various recovery options provided by <span class=\"ph\">RSC<\/span>.<\/p>","href":"aws\/aws_s3_tables_recovery.html","attributes":{"data-id":"aws_s3_tables_recovery"},"menu":{"hasChildren":false},"tocID":"aws_s3_tables_recovery-d39307e19956","next":"aws_s3_tables_recovery-d39307e19956"}]}};